INSERT INTO grammar_patterns (slug, label, tooltip, endings) VALUES
    ('proposal', 'Proposal', 'A tentative first-person offer or suggestion to do something — "Shall I/we...?" — distinct from a flat statement of intent and from the unrelated conjecture use of the same -(으)ㄹ까 ending with a non-volitional or third-person subject.', '-(으)ㄹ까(요)');
